<script setup>
import FriendlyIcon from './FriendlyIcon.vue'
import { computed, ref, watch, onBeforeUnmount } from 'vue'
import { agricultureAssetContentUrl } from './api.js'
import './live-field.css'
const props = defineProps({ live:Object, view:String, workspaceId:String, pending:Boolean, error:String, uncertain:Boolean })
const emit = defineEmits(['action','explain','capture-source','capture-add','reconcile','retry','create-task','register-device'])
const mobilePage = ref('monitor'), mobileMetric=ref('temperature')
const mobilePoints=computed(()=>{const values=props.live.samples.map(x=>Number(x[mobileMetric.value])).filter(Number.isFinite);const min=Math.min(...values),range=Math.max(...values)-min||1;return values.map((v,i)=>`${20+i*260/Math.max(values.length-1,1)},${115-(v-min)/range*90}`).join(' ')})
const mobileTicks=computed(()=>{const values=props.live.samples.map(x=>x.temperature).filter(Number.isFinite);return values.length?[Math.max(...values).toFixed(1),Math.min(...values).toFixed(1)]:['—','—']})
function dualPoints(metric){const samples=props.live.samples,values=samples.map(s=>s.temperature).filter(Number.isFinite);const lo=metric==='humidity'?0:Math.min(...values),hi=metric==='humidity'?100:Math.max(...values);return samples.flatMap((v,i)=>Number.isFinite(v[metric])?[`${28+i*244/Math.max(samples.length-1,1)},${110-(v[metric]-lo)/(hi-lo||1)*85}`]:[]).join(' ')}
const dualTimes=computed(()=>{const samples=props.live.samples;return [...new Set([0,Math.floor((samples.length-1)/2),samples.length-1])].filter(i=>i>=0&&samples[i]).map(i=>({x:28+i*244/Math.max(samples.length-1,1),value:samples[i].observedAt}))})
const demoSettingsOpen = ref(false), historyOpen = ref(false)
const selected = ref(''), inventoryCategory = ref('全部'), inventoryDetail = ref('');
const inventory = computed(() => props.live.inventory || []);
const inventoryCategories = computed(() => ['全部', ...new Set(inventory.value.map(item => item.category))]);
const filteredInventory = computed(() => inventory.value.filter(item => inventoryCategory.value === '全部' || item.category === inventoryCategory.value));
const inventoryStatus = status => ({online:'在线',paused:'已暂停',stale:'数据已过期',disconnected:'连接中断',offline:'离线',unconnected:'待接入'})[status] || '等待状态更新';
const clock = ref(Date.now())
const clockTimer = setInterval(() => {clock.value = Date.now()}, 1000)
onBeforeUnmount(() => clearInterval(clockTimer))
watch(() => props.live.cameras, cameras => { if (!cameras.some(c => c.id === selected.value)) selected.value = cameras[0]?.id || '' }, {immediate:true})
const camera = computed(() => props.live.cameras.find(c => c.id === selected.value))
const latest = computed(() => props.live.samples.at(-1) || {})
const metrics = [{key:'temperature',label:'空气温度',unit:'°C',color:'#c18a45'},{key:'humidity',label:'空气湿度',unit:'%',color:'#6497ad'},{key:'soil_moisture',label:'土壤含水率',unit:'%',color:'#6c9873'}]
const scenarios = {normal:'正常巡检',humidity_change:'湿度变化',leaf_anomaly:'叶片异常'}
const states = {idle:'等待巡检',patrolling:'巡检中',paused:'已暂停',returning:'返航中',docked:'充电点待命'}
const time = value => value ? new Date(typeof value === 'number' ? value * 1000 : value).toLocaleTimeString('zh-CN') : '等待更新'
const stale = computed(() => props.live.status === 'stale' || clock.value - new Date(typeof props.live.observedAt === 'number' ? props.live.observedAt * 1000 : props.live.observedAt).getTime() > props.live.staleAfterSeconds * 1000)
const statusText = computed(() => props.error || props.live.status === 'disconnected' ? '连接中断' : props.live.paused ? '已暂停' : stale.value ? '数据已过期' : '在线')
const dock = computed(() => props.live.robot?.route?.[0] || {x:.1,y:.2})
const blocked = computed(() => props.pending || props.uncertain || stale.value || !!props.error || props.live.status !== 'online')
function trend(key) { const values = props.live.samples.map(s => Number(s[key])).filter(Number.isFinite); const min=Math.min(...values)-1,max=Math.max(...values)+1; return values.map((v,i) => `${i*160/Math.max(values.length-1,1)},${37-(v-min)/(max-min)*30}`).join(' ') }
function action(name,extra={}) { emit('action',name,extra) }
</script>
<template>
  <div class="live-field" :class="[`live-${view}`, {'live-paused':live.paused}, `mobile-page-${mobilePage}`]">
    <header class="field-mobile-header"><button v-if="mobilePage!=='monitor' && view!=='devices'" @click="mobilePage='monitor'">‹ 园区监控</button><h2>{{ view==='devices' ? '农业设备' : mobilePage==='camera' ? '现场相机' : mobilePage==='robot' ? '巡检机器人' : '园区监控' }}</h2><p>{{ view==='devices' ? '查看园区设备状态，了解数据来源。' : mobilePage==='camera' ? '查看现场画面，留存关键时刻。' : mobilePage==='robot' ? '按计划园区巡检，帮助发现需要关注的地方。' : '查看实时读数与变化，发现异常及时处理。' }}</p><nav v-if="view!=='devices' && mobilePage==='monitor'"><button :class="{selected:mobilePage==='monitor'}" @click="mobilePage='monitor'">环境读数</button><button :class="{selected:mobilePage==='camera'}" @click="mobilePage='camera'">现场相机</button><button :class="{selected:mobilePage==='robot'}" @click="mobilePage='robot'">巡检机器人</button></nav></header><div class="live-banner"><span><i :class="{'is-stale':stale || error}"></i>{{ live.label }}</span><strong>{{ error || live.status === 'disconnected' ? '连接中断' : live.paused ? '演示已暂停' : stale ? '数据已过期' : '现场更新中' }}</strong></div>
    <details class="live-demo-settings" @toggle="demoSettingsOpen = $event.target.open"><summary>更多 · 演示设置</summary></details><div v-show="demoSettingsOpen" class="live-toolbar"><label>演示场景 <select :value="live.scenario" :disabled="blocked" @change="action('scenario.set',{scenario:$event.target.value})"><option v-for="(name,id) in scenarios" :key="id" :value="id">{{ name }}</option></select></label><button :disabled="blocked" @click="action(live.paused ? 'demo.resume' : 'demo.pause')">{{ live.paused ? '继续演示' : '暂停演示' }}</button><small>更新于 {{ time(live.observedAt) }}</small></div>
    <p v-if="error" class="agri-error" role="alert">{{ error }} <button @click="emit('reconcile')">刷新并核对状态</button></p><p v-if="uncertain" role="status">操作结果尚未确认，刷新可查看最新状态；请重试原请求以确认结果。<button :disabled="pending" @click="emit('retry')">重试此操作</button></p>
    <div v-if="view !== 'devices'" class="live-metrics"><article v-for="metric in metrics" :key="metric.key" class="agri-card"><FriendlyIcon :name="metric.key === 'temperature' ? 'temperature' : metric.key === 'humidity' ? 'water' : 'seed'"/><span>{{ metric.label }}</span><strong>{{ latest[metric.key]?.toFixed(1) ?? '—' }}<small>{{ metric.unit }}</small></strong><svg viewBox="0 0 160 42" role="img" :aria-label="`${metric.label}近期趋势`"><polyline :points="trend(metric.key)" fill="none" :stroke="metric.color" stroke-width="2.5"/></svg><small class="live-metric-meta">{{ live.samples.length ? `最近 ${live.samples.length} 次观测 · ${time(latest.observedAt)}` : '所选地块无监测绑定' }}</small></article></div>
    <section v-if="view === 'devices' && inventory.length" class="agri-card inventory-section"><div class="agri-section-title"><h2>园区设备台账 <small>{{ inventory.length }} 台</small></h2><small>模拟部署</small></div><div class="workspace-filters"><button v-for="category in inventoryCategories" :key="category" :class="{selected:inventoryCategory === category}" @click="inventoryCategory = category">{{ category }}</button></div><div class="inventory-grid"><article v-for="device in filteredInventory" :key="device.id" class="inventory-card"><header><span class="inventory-category">{{ device.category }}</span><span :class="['inventory-status',device.status]">● {{ inventoryStatus(device.status) }}</span></header><h3><FriendlyIcon :name="/相机|摄像/.test(device.name)?'camera':/水|灌|湿/.test(device.name)?'water':/机器人|无人/.test(device.name)?'robot':'leaf'"/>{{ device.name }}</h3><p>{{ device.summary }}</p><dl><div v-for="metric in device.metrics || []" :key="metric.key"><dt>{{ metric.label }}</dt><dd>{{ metric.value }}<small>{{ metric.unit }}</small></dd></div></dl><footer><small>更新于 {{ time(device.observedAt) }}</small><button @click="inventoryDetail = inventoryDetail === device.id ? '' : device.id" :aria-expanded="inventoryDetail === device.id"><span class="inventory-desktop-detail-label">{{ inventoryDetail === device.id ? '收起详情' : '设备详情' }}</span><span class="inventory-mobile-detail-label">{{ inventoryDetail === device.id ? '⌃' : '›' }}</span></button></footer><div v-if="inventoryDetail === device.id" class="inventory-detail"><p>{{ device.summary }}</p><small>设备编号 {{ device.id }} · 模拟设备 · {{ device.category }} · 更新于 {{ time(device.observedAt) }}</small><p v-if="device.sources?.length">设备能力参考</p><a v-for="(url,index) in device.sources || []" :key="url" :href="url" target="_blank" rel="noopener noreferrer">官方资料 {{ index + 1 }} ↗</a></div></article></div></section>
    <section v-if="view!=='devices'" class="field-mobile-trend"><h3>最近趋势 <small>模拟观测</small></h3><div class="dual-trend-legend"><span style="color:#165442">&#9679; &#28201;&#24230; (&#176;C)</span><span style="color:#2189e8">&#9679; &#28287;&#24230; (%)</span></div><svg v-if="live.samples.length" viewBox="0 0 300 145" role="img" aria-label="Temperature and humidity recorded trends"><path d="M28 20V115H272V20" stroke="#c7d5cb" fill="none"/><path d="M28 70H272M28 25H272" stroke="#edf1ed"/><text x="0" y="25">{{ mobileTicks[0] }}</text><text x="0" y="110">{{ mobileTicks[1] }}</text><text x="278" y="25">100</text><text x="278" y="70">50</text><text x="278" y="113">0</text><polyline :points="dualPoints('temperature')" stroke="#165442" stroke-width="2" fill="none"/><polyline :points="dualPoints('humidity')" stroke="#2189e8" stroke-width="2" fill="none"/><text v-for="tick in dualTimes" :key="tick.x" :x="tick.x" y="138" text-anchor="middle">{{ time(tick.value) }}</text></svg><p v-else>&#26242;&#26080;&#35266;&#27979;&#35760;&#24405;</p><small>来源：模拟传感器 · {{ time(latest.observedAt) }}</small></section><article v-if="view!=='devices'" class="field-mobile-check"><h3>现场核对</h3><p>请核查现场与设备状态，再判断是否需要处理。</p><button :disabled="blocked" @click="emit('create-task',{title:'核查园区环境读数',description:`核对观测时间 ${time(latest.observedAt)} 的环境变化、现场情况及设备状态。`})">创建核查待办 ›</button></article><div class="live-scene-grid">
      <section v-if="view !== 'devices'" class="agri-card live-camera"><div class="agri-section-title"><h2>园里此刻</h2><select class="desktop-camera-select" v-model="selected" aria-label="选择摄像头"><option v-for="cam in live.cameras" :key="cam.id" :value="cam.id">{{ cam.name }}</option></select></div><nav class="mobile-camera-selector" aria-label="选择摄像头"><button v-for="cam in live.cameras" :key="cam.id" :aria-pressed="selected===cam.id" @click="selected=cam.id">{{ cam.name }}</button></nav><div class="live-camera-frame"><img v-if="camera?.assetId" :src="agricultureAssetContentUrl(workspaceId,camera.assetId)" :alt="`${camera.name}模拟画面`"><div v-else class="live-no-image">等待模拟画面</div><span class="live-camera-tag">● {{ scenarios[live.scenario] }} · {{ time(camera?.observedAt) }}</span><div class="live-scan"></div><span class="live-frame-label">模拟摄像头 · 非实景视频</span></div><footer><span>{{ camera?.name }} · {{ statusText === '在线' ? (camera?.status === 'online' ? '在线' : '暂停更新') : statusText }}</span><button :disabled="blocked || camera?.status !== 'online' || !camera?.assetId" @click="action('camera.capture',{cameraId:camera.id})">◎ 抓拍并保存</button></footer></section>
      <section v-if="live.robot" class="agri-card live-robot"><div class="agri-section-title"><h2>园区巡检</h2><span class="live-online">● {{ statusText }}</span></div><div class="mobile-robot-scene"><img src="/friendly/vineyard-aerial-v1.png" alt="葡萄园俯视模拟示意图"><span class="robot-state-pill">{{ states[live.robot.state] || '状态未知' }} · 模拟巡检</span><svg viewBox="0 0 400 500" role="img" aria-label="模拟机器人实际路线位置"><polyline :points="live.robot.route.map(p=>`${p.x*340+30},${p.y*350+35}`).join(' ')" fill="none" stroke="white" stroke-width="5" stroke-dasharray="10 8"/><g :transform="`translate(${dock.x*340+30},${dock.y*350+35})`"><circle r="20" fill="#165442" stroke="white" stroke-width="3"/><path d="M-10 0L0-10 10 0M-7-2V10H7V-2M-2 10V3H2V10" fill="none" stroke="white" stroke-width="3"/></g><g :transform="`translate(${live.robot.position.x*340+30},${live.robot.position.y*350+35})`"><rect x="-19" y="-17" width="38" height="34" rx="11" fill="white" stroke="#165442" stroke-width="2"/><rect x="-13" y="-10" width="26" height="15" rx="5" fill="#165442"/><circle cx="-6" cy="-3" r="3" fill="#adf5dd"/><circle cx="6" cy="-3" r="3" fill="#adf5dd"/><path d="M-20 8V18M20 8V18M0-18V-25" stroke="#165442" stroke-width="5"/><circle cy="-26" r="4" fill="white"/></g></svg><div class="robot-glass"><label>巡检进度 <progress max="100" :value="live.robot.progress"></progress><strong>{{ Number.isFinite(live.robot.progress) ? live.robot.progress.toFixed(0)+'%' : '未知' }}</strong></label><label>电量 <meter min="0" max="100" :value="live.robot.battery"></meter><strong>{{ Number.isFinite(live.robot.battery) ? live.robot.battery.toFixed(0)+'%' : '未知' }}</strong></label></div></div><svg class="live-map" viewBox="0 0 400 240" role="img" aria-label="园区示意地图与机器人位置，坐标仅用于演示"><rect width="400" height="240" rx="14" fill="#f0f3e7"/><g v-for="y in [48,78,108,138,168]" :key="y"><g v-for="x in [40,66,92,118,144,170,196,222,248,274]" :key="x" :transform="`translate(${x},${y})`"><path d="M0 3V12" stroke="#947a44" stroke-width="3"/><ellipse rx="11" ry="8" fill="#8bae59"/><circle cx="-5" cy="-3" r="7" fill="#bad477"/><circle cx="5" cy="-3" r="7" fill="#a0c75f"/><circle cx="2" cy="5" r="3" fill="#786895"/></g></g><rect x="305" y="190" width="70" height="30" rx="10" fill="#cee3dd" stroke="#8eb6ac"/><text x="322" y="210">育苗棚</text><text x="42" y="27">葡萄种植区</text><g :transform="`translate(${dock.x*360+20},${dock.y*200+20})`"><circle r="18" fill="#dcd3a8"/><text x="-20" y="-23">⚡充电点</text></g><polyline :points="live.robot.route.map(p=>`${p.x*360+20},${p.y*200+20}`).join(' ')" fill="none" stroke="#d6a159" stroke-width="3" stroke-dasharray="6 5"/><g :transform="`translate(${live.robot.position.x*360+20},${live.robot.position.y*200+20})`"><ellipse cy="12" rx="16" ry="5" fill="#193b3144"/><rect x="-13" y="-10" width="26" height="23" rx="8" fill="#fff" stroke="#57757c" stroke-width="2"/><rect x="-9" y="-6" width="18" height="10" rx="4" fill="#29494b"/><circle cx="-4" cy="-1" r="2" fill="#8fe5ee"/><circle cx="4" cy="-1" r="2" fill="#8fe5ee"/><rect x="-15" y="7" width="5" height="9" rx="2" fill="#344744"/><rect x="10" y="7" width="5" height="9" rx="2" fill="#344744"/><path d="M0-10V-16" stroke="#526c68" stroke-width="2"/><circle cy="-17" r="3" fill="#83c5c4"/></g></svg><small class="agri-muted">园区示意 · 路线与坐标为模拟</small><h3>{{ live.robot.name }} <small>{{ states[live.robot.state] }}</small></h3><div class="live-robot-stats"><label>电量 <strong>{{ live.robot.battery.toFixed(0) }}%</strong><meter min="0" max="100" :value="live.robot.battery">电量</meter></label><label>巡检进度 <strong>{{ live.robot.progress.toFixed(0) }}%</strong><progress max="100" :value="live.robot.progress"></progress></label></div><div class="live-controls"><button :disabled="blocked || live.robot.state === 'patrolling'" @click="action('robot.start')">开始巡检</button><button :disabled="blocked || !['patrolling','returning'].includes(live.robot.state)" @click="action('robot.pause')">暂停</button><button :disabled="blocked || live.robot.state === 'returning'" @click="action('robot.return')">返航充电</button></div></section>
      <section v-else class="agri-card live-robot"><h2>园区巡检</h2><p class="agri-muted">所选地块未绑定演示巡检机器人。</p></section>
    </div>

    <section v-if="view === 'devices'" class="agri-card"><h2>接入设备</h2><p>连接真实设备后，可核验数据。</p><button @click="emit('register-device')">登记设备 ›</button><details class="device-connection-details"><summary>查看连接台账</summary><h3>现场连接</h3><div v-for="cam in live.cameras" :key="cam.id" class="agri-row"><span>{{ cam.name }}<small>摄像头 · 最近画面 {{ time(cam.observedAt) }}</small></span><span class="live-online">● {{ statusText === '在线' ? (cam.status === 'online' ? '在线' : '已暂停') : statusText }}</span></div><div class="agri-row"><span>园区环境与土壤传感器<small>温度 / 湿度 / 土壤含水率</small></span><span class="live-online">● {{ live.samples.length ? statusText : '无监测绑定' }}</span></div></details></section>
    <details v-if="view === 'overview'" class="live-history-toggle" @toggle="historyOpen = $event.target.open"><summary>现场动态与抓拍 · {{ live.events.length }} 条动态 / {{ live.captures.length }} 张抓拍</summary></details><div v-show="view !== 'overview' || historyOpen">
    <section class="agri-card live-events"><div class="agri-section-title"><h2>最新现场动态</h2><button @click="emit('explain',`请结合当前园区记录解释${scenarios[live.scenario]}场景中的变化，区分已知事实与需要现场核实的事项。`)">让澍雨解释这次变化 →</button></div><ol><li v-for="event in live.events.slice(-6).reverse()" :key="event.id" :class="{'live-warning':event.severity === 'warning'}"><time>{{ time(event.observedAt) }}</time><span>{{ event.message }}</span></li></ol><p v-if="!live.events.length" class="agri-muted">巡检开始后，现场动态会记录在这里。</p></section>
    <section v-if="view !== 'devices' && live.captures.length" class="agri-card"><h2>最近抓拍</h2><div class="live-captures"><article v-for="capture in live.captures.slice(-3).reverse()" :key="capture.id"><img v-if="capture.assetId" :src="agricultureAssetContentUrl(workspaceId,capture.assetId)" alt="演示场景抓拍"><small>✓ 已保存到现场资料 · {{ time(capture.observedAt) }} · 模拟抓拍</small><button :disabled="!capture.assetId" @click="emit('capture-source',capture)">查看来源</button><button :disabled="!capture.assetId" @click="emit('capture-add',capture)">加入本轮对话</button></article></div></section>
    </div>
  </div>
</template>
